-- Phase 4, M1: trust score.
--
-- Plan and the decisions behind every table here:
-- docs/phase-notes/phase-4-trust-score-plan.md (§3 decisions, §6 data model)
--
-- Hand-written rather than generated by `migrate dev`, as with every
-- migration before it: Neon's pooled endpoint gives Prisma no shadow
-- database. Everything above the HAND-WRITTEN sections is exactly what
-- `prisma migrate diff --from-config-datasource --to-schema` produced; the
-- sections below it are what the schema language cannot express.
-- Apply with `prisma migrate deploy`.
--
-- Purely additive and safe against existing rows:
--
--  * Organization gains four trust settings, all NOT NULL with defaults, so
--    every existing organisation gets the plan's starting values.
--  * PunchEvent gains six columns. `source` defaults to WEB — true of every
--    existing punch, since the web was the only client. The rest are null:
--    pre-Phase-4 punches have no trust evidence, and PunchEvent is
--    append-only, so they can never be backfilled. Adding columns is DDL and
--    does not fire the append-only row trigger.
--  * Five new tables, all empty.

-- CreateEnum
CREATE TYPE "LocationPolicy" AS ENUM ('EITHER', 'BOTH');

-- CreateEnum
CREATE TYPE "PunchSource" AS ENUM ('WEB', 'MOBILE', 'HR');

-- CreateEnum
CREATE TYPE "TrustDecision" AS ENUM ('APPROVED', 'FLAGGED');

-- CreateEnum
CREATE TYPE "DevicePlatform" AS ENUM ('ANDROID', 'IOS');

-- CreateEnum
CREATE TYPE "ChallengePurpose" AS ENUM ('REGISTER', 'ATTENDANCE');

-- CreateEnum
CREATE TYPE "ReviewOutcome" AS ENUM ('UPHELD', 'REJECTED', 'ACCEPTED');

-- AlterTable
ALTER TABLE "Organization" ADD COLUMN     "locationPolicy" "LocationPolicy" NOT NULL DEFAULT 'EITHER',
ADD COLUMN     "trustFenceMarginMeters" INTEGER NOT NULL DEFAULT 25,
ADD COLUMN     "trustMaxAccuracyMeters" INTEGER NOT NULL DEFAULT 50,
ADD COLUMN     "trustMaxSpeedKmh" INTEGER NOT NULL DEFAULT 300;

-- AlterTable
ALTER TABLE "PunchEvent" ADD COLUMN     "decision" "TrustDecision",
ADD COLUMN     "deviceId" TEXT,
ADD COLUMN     "ipAddress" TEXT,
ADD COLUMN     "source" "PunchSource" NOT NULL DEFAULT 'WEB',
ADD COLUMN     "trustReasons" JSONB,
ADD COLUMN     "trustScore" INTEGER;

