-- ─── HAND-WRITTEN 1: one active device per employee (D4) ───────────────────
--
-- A partial unique index: any number of revoked devices per user, at most one
-- that isn't. Registering a replacement phone is "revoke the old, insert the
-- new" in one transaction; the reverse order violates this. Prisma cannot
-- express a partial index, so it exists only here — `migrate diff` will not
-- report it as drift and will not recreate it if dropped.

CREATE UNIQUE INDEX "Device_one_active_per_user"
  ON "Device" ("userId")
  WHERE "revokedAt" IS NULL;

-- A revocation always says who did it. revokeReason stays optional.
ALTER TABLE "Device"
  ADD CONSTRAINT "Device_revocation_complete"
    CHECK (("revokedAt" IS NULL) = ("revokedById" IS NULL));


-- ─── HAND-WRITTEN 2: trust settings that make sense ────────────────────────
--
-- The engine's thresholds. A zero or negative value would silently turn a
-- check off — an accuracy limit of 0 m flags every punch, a speed of 0 km/h
-- flags any movement — so the database refuses them at the point of saving.

ALTER TABLE "Organization"
  ADD CONSTRAINT "Organization_trust_accuracy_range"
    CHECK ("trustMaxAccuracyMeters" BETWEEN 5 AND 1000),
  ADD CONSTRAINT "Organization_trust_margin_range"
    CHECK ("trustFenceMarginMeters" BETWEEN 0 AND 500),
  ADD CONSTRAINT "Organization_trust_speed_range"
    CHECK ("trustMaxSpeedKmh" BETWEEN 10 AND 2000);


-- ─── HAND-WRITTEN 3: trust evidence that adds up ───────────────────────────
--
-- A phone punch without the device that signed it is a phone punch nobody
-- can verify, so MOBILE requires a device (punches and rejected attempts
-- alike). Scores are 0–100 (D8).
--
-- Added as plain CHECKs: Postgres validates them against existing rows, which
-- are all source WEB with a null score, so they pass.

ALTER TABLE "PunchEvent"
  ADD CONSTRAINT "PunchEvent_trust_score_range"
    CHECK ("trustScore" IS NULL OR "trustScore" BETWEEN 0 AND 100),
  ADD CONSTRAINT "PunchEvent_mobile_has_device"
    CHECK ("source" <> 'MOBILE' OR "deviceId" IS NOT NULL);

ALTER TABLE "AttendanceAttempt"
  ADD CONSTRAINT "AttendanceAttempt_trust_score_range"
    CHECK ("trustScore" BETWEEN 0 AND 100),
  ADD CONSTRAINT "AttendanceAttempt_mobile_has_device"
    CHECK ("source" <> 'MOBILE' OR "deviceId" IS NOT NULL);


-- ─── HAND-WRITTEN 4: a challenge is used once, and only for its purpose ────
--
-- Replay protection (plan §5). The API spends a challenge with
-- `UPDATE … SET "usedAt" = now() WHERE "usedAt" IS NULL`, which is already
-- single-use under concurrency. The trigger makes it true for everyone else
-- too: once spent, a row cannot be changed back, and only `usedAt` may ever
-- change. DELETE stays allowed — the expiry sweep removes old rows, and these
-- are not evidence (the punch records what was signed).
--
-- REGISTER happens before a device exists; ATTENDANCE is always for one.

ALTER TABLE "DeviceChallenge"
  ADD CONSTRAINT "DeviceChallenge_device_matches_purpose"
    CHECK (("purpose" = 'REGISTER') = ("deviceId" IS NULL)),
  ADD CONSTRAINT "DeviceChallenge_expires_after_creation"
    CHECK ("expiresAt" > "createdAt");

CREATE FUNCTION "device_challenge_single_use"() RETURNS trigger AS $$
BEGIN
  IF OLD."usedAt" IS NOT NULL THEN
    RAISE EXCEPTION 'DeviceChallenge % has already been used', OLD."id"
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF NEW."id" IS DISTINCT FROM OLD."id"
     OR NEW."userId" IS DISTINCT FROM OLD."userId"
     OR NEW."deviceId" IS DISTINCT FROM OLD."deviceId"
     OR NEW."purpose" IS DISTINCT FROM OLD."purpose"
     OR NEW."challenge" IS DISTINCT FROM OLD."challenge"
     OR NEW."expiresAt" IS DISTINCT FROM OLD."expiresAt"
     OR NEW."createdAt" IS DISTINCT FROM OLD."createdAt" THEN
    RAISE EXCEPTION 'DeviceChallenge rows may only be marked used'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "DeviceChallenge_single_use"
  BEFORE UPDATE ON "DeviceChallenge"
  FOR EACH ROW EXECUTE FUNCTION "device_challenge_single_use"();


-- ─── HAND-WRITTEN 5: a ruling fits what it rules on (D7) ───────────────────
--
-- Exactly one of punch / attempt. A flagged punch is UPHELD or REJECTED; a
-- rejected attempt can only be ACCEPTED (declining it needs no row — it
-- stays rejected), and accepting one must name the punch HR created.

ALTER TABLE "AttendanceReview"
  ADD CONSTRAINT "AttendanceReview_one_subject"
    CHECK (num_nonnulls("punchEventId", "attendanceAttemptId") = 1),
  ADD CONSTRAINT "AttendanceReview_outcome_fits_subject"
    CHECK (
      ("punchEventId" IS NOT NULL AND "outcome" IN ('UPHELD', 'REJECTED') AND "createdPunchId" IS NULL)
      OR
      ("attendanceAttemptId" IS NOT NULL AND "outcome" = 'ACCEPTED' AND "createdPunchId" IS NOT NULL)
    );


-- ─── HAND-WRITTEN 6: attempts and rulings are append-only ──────────────────
--
-- Same guarantee as PunchEvent (Phase 3), for the same reason: these are the
-- record of what happened and what HR decided. A wrong ruling is answered by
-- a later feature, never by editing this one. One function for both tables;
-- the message names the table. TRUNCATE stays allowed for the e2e reset, as
-- with PunchEvent.

CREATE FUNCTION "row_is_append_only"() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION '% rows are append-only: % is not allowed', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "AttendanceAttempt_append_only"
  BEFORE UPDATE OR DELETE ON "AttendanceAttempt"
  FOR EACH ROW EXECUTE FUNCTION "row_is_append_only"();

CREATE TRIGGER "AttendanceReview_append_only"
  BEFORE UPDATE OR DELETE ON "AttendanceReview"
  FOR EACH ROW EXECUTE FUNCTION "row_is_append_only"();

